(function(root){
'use strict';
function detectorStatus(list){const ran=list.filter(d=>d.available===true&&typeof d.is_watermarked==='boolean');return {ran:ran.length,unavailable:list.length-ran.length,flagged:ran.filter(d=>d.is_watermarked).length,label:!ran.length?'Unavailable':ran.some(d=>d.is_watermarked)?'Signal reported':'No signal in configured tests'};}
function detectorReason(d){if(d.available===true)return 'Valid only for the matching generation scheme, settings, and keys. It does not test arbitrary vendor watermarks.';if(d.detector==='markllm')return 'Matching generation configuration and keys, plus the MarkLLM runtime, are not configured.';if(d.detector==='gumbel')return 'The generation key and matching tokenizer / replay configuration are not configured.';if(d.detector==='claude-text')return 'This adapter is a placeholder in the installed engine; it cannot run a test.';return 'Detector could not run. See the full report for details.';}
function codePointRange(text,span){const points=Array.from(text);if(!Array.isArray(span)||span.length!==2||!span.every(Number.isInteger)||span[0]<0||span[1]<span[0]||span[1]>points.length)return null;return {offset:points.slice(0,span[0]).join('').length,end:points.slice(0,span[1]).join('').length};}
function summarize(changes){if(!changes.length)return 'No changes selected. Your export matches the reviewed original.';const spaces=changes.filter(c=>c.kind==='character'&&c.after===' ').length;const removals=changes.filter(c=>c.kind==='character'&&c.after==='').length;const style=changes.filter(c=>c.kind==='style').length;return `${changes.length} selected change${changes.length===1?'':'s'}: `+[spaces&&`${spaces} space${spaces===1?'':'s'} standardized`,removals&&`${removals} hidden character${removals===1?'':'s'} removed`,style&&`${style} editorial edit${style===1?'':'s'}`].filter(Boolean).join(' · ');}
root.ReviewModel={detectorStatus,detectorReason,codePointRange,summarize};if(typeof module!=='undefined')module.exports=root.ReviewModel;
})(globalThis);
